actions.script:
const ids = String(selectedPartyIds || '').split(',').map((id) => id.trim()).filter((id) => id)
if (!ids.length) { ec.message.addError(ec.l10n.localize('Select one or more contacts first')); return }
if (!contactBookGroupId) { ec.message.addError(ec.l10n.localize('Choose the group')); return }
const out = ec.service.sync().name('mantle.party.ContactBookServices.add#ContactBookGroupParties').parameters({contactBookGroupId: contactBookGroupId,
    partyIdList: ids}).call()
if (!ec.message.hasError()) ec.message.addMessage(ec.resource.expand('${count} added to the group', '', {count: ids.length - (out?.failedPartyIdList?.length || 0)}), 'success')

const ids = String(selectedPartyIds || '').split(',').map((id) => id.trim()).filter((id) => id)
if (!ids.length) { ec.message.addError(ec.l10n.localize('Select one or more contacts first')); return }
if (!contactBookId) { ec.message.addError(ec.l10n.localize('Choose the book')); return }
const out = ec.service.sync().name('mantle.party.ContactBookServices.add#ContactBookParties').parameters({contactBookId: contactBookId, partyIdList: ids}).call()
if (!ec.message.hasError()) ec.message.addMessage(ec.resource.expand('${added} added to the book, ${already} already in it', '',
        {added: out?.addedCount || 0, already: out?.alreadyCount || 0}), 'success')

const ids = String(selectedPartyIds || '').split(',').map((id) => id.trim()).filter((id) => id)
if (!ids.length) { ec.message.addError(ec.l10n.localize('Select one or more contacts first')); return }
const out = ec.service.sync().name('mantle.party.ContactBookServices.remove#ContactBookParties').parameters({contactBookId: contactBookId, partyIdList: ids}).call()
if (!ec.message.hasError()) ec.message.addMessage(ec.resource.expand('${count} removed from the book', '', {count: out?.removedCount || 0}), 'success')

const ids = String(selectedPartyIds || '').split(',').map((id) => id.trim()).filter((id) => id)
const out = ec.service.sync().name('ironstone.ContactServices.export#ContactFile').parameters({partyIdList: ids, format: format === 'csv' ? 'csv' : 'vcard'}).call()
if (!ec.message.hasError() && out?.location) ec.web.sendResourceResponse(out.location, false)
else ec.web.sendJsonResponse({})

const ids = String(selectedPartyIds || '').split(',').map((id) => id.trim()).filter((id) => id)
if (ids.length !== 2) { ec.message.addError(ec.l10n.localize('Select exactly two contacts to merge')); return }
comparePartyId = ids[0]
compareOtherPartyId = ids[1]

const ids = String(selectedPartyIds || '').split(',').map((id) => id.trim()).filter((id) => id)
if (!ids.length) { ec.message.addError(ec.l10n.localize('Select one or more contacts first')); return }
// each on its own (mantle.party.ContactBookServices.delete#Contacts): removed when nothing refers to it, else disabled and
// out of its books; one that may not be deleted is a warning and the rest go
const out = ec.service.sync().name('mantle.party.ContactBookServices.delete#Contacts').parameters({partyIdList: ids}).call()
if (!ec.message.hasError()) {
    ec.message.addMessage(ec.resource.expand('${count} deleted', '', {count: (out?.removedCount || 0) + (out?.disabledCount || 0)}), 'success')
    if (partyId && !(out?.failedPartyIdList || []).includes(partyId) && ids.includes(partyId)) partyId = null
}
